using System;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Tests;

public sealed class DbFixture : IDisposable
{
    public string Connection { get; } = "memory";
    public void Dispose() { }
}

/// <summary>
/// Shared fixture holder replacing xUnit's ICollectionFixture.
/// Both test classes share this single instance and are marked
/// [DoNotParallelize] to preserve the original serial execution.
/// </summary>
internal static class DbFixtureHolder
{
    private static readonly Lazy<DbFixture> _instance = new(() => new DbFixture());
    public static DbFixture Instance => _instance.Value;

    [AssemblyCleanup]
    public static void Cleanup() => _instance.Value.Dispose();
}

[TestClass]
public static class AssemblyHook
{
    [AssemblyCleanup]
    public static void DisposeFixtures() => DbFixtureHolder.Instance.Dispose();
}

